#!/usr/bin/env bash
# Generated by xforge_sure_bridge for SURE tool-agent local bootstrap.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/../../../.." && pwd)"
REPO_ROOT="$(readlink -f "${REPO_ROOT}")"
ARTIFACTS_DIR="${SCRIPT_DIR}/artifacts"
mkdir -p "${ARTIFACTS_DIR}"
LOG_PATH="${ARTIFACTS_DIR}/local_uv_setup.log"
export UV_CACHE_DIR="${SCRIPT_DIR}/.runtime/uv-cache"
mkdir -p "${UV_CACHE_DIR}"

cd "${SCRIPT_DIR}"

PYTHON_BIN="${PYTHON_BIN:-python3.12}"
if ! command -v "${PYTHON_BIN}" >/dev/null 2>&1; then
  PYTHON_BIN="${PYTHON_FALLBACK:-python3.11}"
fi
if ! command -v "${PYTHON_BIN}" >/dev/null 2>&1; then
  PYTHON_BIN="python3"
fi
if ! command -v "${PYTHON_BIN}" >/dev/null 2>&1; then
  echo "No usable Python found. Tried python3.12, python3.11, and python3" | tee "${LOG_PATH}" >&2
  exit 1
fi
if ! command -v uv >/dev/null 2>&1; then
  echo "uv is required for local tool-agent bootstrap" | tee "${LOG_PATH}" >&2
  exit 1
fi

{
  echo "PYTHON_BIN=${PYTHON_BIN}"
  uv --version
  uv venv --python "${PYTHON_BIN}" .venv
  uv pip install --index-strategy unsafe-best-match --python .venv/bin/python -r requirements-local.txt
  if [ "${INSTALL_SURE_EDITABLE:-0}" = "1" ] && [ -f "${REPO_ROOT}/pyproject.toml" ]; then
    uv pip install --python .venv/bin/python --no-deps -e "${REPO_ROOT}"
  fi
  .venv/bin/python --version
} 2>&1 | tee "${LOG_PATH}"

.venv/bin/python - <<'PY'
import json
import platform
from datetime import datetime, timezone
from pathlib import Path

model_dir = Path(__file__).resolve().parent
artifacts = model_dir / "artifacts"
payload = {
    "status": "setup_completed",
    "checked_at": datetime.now(timezone.utc).isoformat(),
    "venv_path": str((model_dir / ".venv").resolve()),
    "python": {
        "path": str((model_dir / ".venv" / "bin" / "python").resolve()),
        "version": platform.python_version(),
    },
    "setup_log": str((artifacts / "local_uv_setup.log").resolve()),
}
(artifacts / "local_uv_env.json").write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
PY
